        ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{(byte)0x8c,(byte)0x82,(byte)0x98});out.write(MmsStore.ascii("incoming-fixture"));out.write(0);out.write(new byte[]{(byte)0x8d,(byte)0x92,(byte)0x89});byte[] from=MmsStore.ascii(number);out.write(from.length+2);out.write(0x80);out.write(from);out.write(0);out.write(new byte[]{(byte)0x8a,(byte)0x80,(byte)0x8e,2,4,0,(byte)0x88,4,(byte)0x81,2,0x0e,0x10,(byte)0x83});out.write(MmsStore.ascii(location));out.write(0);return out.toByteArray();
